#include <Keypad.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// --- НАСТРОЙКА КЛАВИАТУРЫ ---
// ВАЖНО: Сверьте пины с вашей схемой! На фото клавиатура подключена к 8 проводам.
// Если в Tinkercad вы подключали к другим пинам, измените цифры ниже.
const byte ROWS = 4; 
const byte COLS = 4; 
char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
byte rowPins[ROWS] = {2, 3, 4, 5}; // Пины строк (проверьте!)
byte colPins[COLS] = {6, 7, 8, 9}; // Пины столбцов (проверьте!)
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

// --- НАСТРОЙКА ДИСПЛЕЯ ---
LiquidCrystal_I2C lcd(0x27, 16, 2); // Если экран не I2C, используйте LiquidCrystal lcd(...)

// --- НАСТРОЙКА ПИНОВ ---
const int buzzerPin = 10;  // Пин зуммера (сверьте с фото)
const int ledRed = 11;     // Красный светодиод
const int ledGreen = 12;   // Зеленый светодиод

// --- ПЕРЕМЕННЫЕ БОМБЫ ---
String correctCode = "12345"; // Код обезвреживания
String inputCode = "";
bool isDefused = false;
bool isExploded = false;
unsigned long startTime;
const unsigned long bombTime = 60000; // Время до взрыва (60 000 мс = 60 секунд)

void setup() {
  Serial.begin(9600);
  lcd.init();
  lcd.backlight();

  pinMode(buzzerPin, OUTPUT);
  pinMode(ledRed, OUTPUT);
  pinMode(ledGreen, OUTPUT);

  lcd.setCursor(0, 0);
  lcd.print("BOMB ACTIVATED");
  delay(1000);

  startTime = millis(); // Запускаем таймер
}

void loop() {
  // Если бомба взорвалась или обезврежена — ничего не делаем
  if (isExploded || isDefused) return;

  // 1. СЧИТАЕМ ОСТАВШЕЕСЯ ВРЕМЯ
  unsigned long elapsed = millis() - startTime;
  long timeLeft = (bombTime - elapsed) / 1000; // Переводим в секунды

  // Если время вышло — ВЗРЫВ
  if (timeLeft <= 0) {
    explodeBomb();
    return;
  }

  // 2. ВЫВОДИМ ВРЕМЯ НА ЭКРАН
  lcd.setCursor(0, 0);
  lcd.print("Time: ");
  lcd.print(timeLeft);
  lcd.print("   "); // Пробелы, чтобы стирать старые цифры

  // 3. ВЫВОДИМ ВВЕДЕННЫЙ КОД
  lcd.setCursor(0, 1);
  lcd.print("Code: ");
  lcd.print(inputCode);
  lcd.print("      ");

  // 4. ПИЩИМ В ЗАВИСИМОСТИ ОТ ВРЕМЕНИ (Нарастающий период)
  // Чем меньше времени, тем чаще писк
  int beepInterval = 1000; // По умолчанию раз в секунду
  if (timeLeft < 10) beepInterval = 200; // Если меньше 10 сек - 5 раз в секунду
  else if (timeLeft < 30) beepInterval = 500; // Если меньше 30 сек - 2 раза в секунду

  // Неблокирующий писк (используем millis, чтобы не тормозить клавиатуру)
  static unsigned long lastBeep = 0;
  if (millis() - lastBeep > beepInterval) {
    tone(buzzerPin, 1000, 50); // Пищим 50 мс
    lastBeep = millis();
  }

  // 5. ОПРАШИВАЕМ КЛАВИАТУРУ
  char key = keypad.getKey();
  if (key) {
    if (key >= '0' && key <= '9') {
      if (inputCode.length() < 5) {
        inputCode += key;
        tone(buzzerPin, 1500, 50); // Короткий писк при нажатии
      }
    }

    // Если ввели 5 символов — проверяем
    if (inputCode.length() == 5) {
      if (inputCode == correctCode) {
        defuseBomb();
      } else {
        // Неправильный код
        lcd.clear();
        lcd.setCursor(0, 0);
        lcd.print("WRONG CODE!");
        tone(buzzerPin, 200, 1000); // Звук ошибки
        delay(1000);
        inputCode = ""; // Сброс кода
        lcd.clear();
      }
    }

    // Сброс кода по кнопке '*'
    if (key == '*') {
      inputCode = "";
    }
  }
}

// --- ФУНКЦИЯ ВЗРЫВА ---
void explodeBomb() {
  isExploded = true;
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("BOOM! EXPLODED");
  digitalWrite(ledRed, HIGH);

  // Долгий прерывистый звук взрыва
  for (int i = 0; i < 10; i++) {
    tone(buzzerPin, 100);
    delay(100);
    noTone(buzzerPin);
    delay(100);
  }
  digitalWrite(buzzerPin, LOW);
}

// --- ФУНКЦИЯ ОБЕЗВРЕЖИВАНИЯ ---
void defuseBomb() {
  isDefused = true;
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("DEFUSED!");
  digitalWrite(ledGreen, HIGH);
  noTone(buzzerPin); // Выключаем писк
  tone(buzzerPin, 2000, 500); // Звук успеха
}
